import type { StableDiagnosisResult, ConfigurationAggregate } from "../diagnosis/types";
import type { ExperimentResult } from "../experiments/types";

/**
 * Deterministic analysis of RECORDED trajectories. Every field here is computed
 * from what the harness logged for each turn (tool calls, per-request
 * compaction metadata, termination); nothing is generated by a model and nothing
 * is hand-entered. The UI labels these as "observed". Interpretation (why the
 * agent behaved this way) is deliberately NOT computed here.
 */

/** Exact prefix written by the read_file tool executor (src/lib/agent/tools.ts) when file content is unchanged since the last read. */
const DEDUP_MARKER = /^\(unchanged since your last read of/;

export interface StaleReadFinding {
  turn: number;
  path: string;
  /** Turn at which this path's earlier result had been replaced by a placeholder, or null if it never was. */
  compactedAtTurn: number | null;
}

export type StepKind = "list" | "read" | "read_marker" | "write" | "test" | "build" | "other" | "final";

/** One agent turn, reduced to what it did. `compactedNow` are the paths whose content was replaced by a placeholder just before this turn's request. */
export interface TurnStep {
  turn: number;
  kind: StepKind;
  target: string | null;
  compactedNow: string[];
}

export interface RunFinding {
  runId: string;
  success: boolean;
  terminationReason: string;
  contextPolicy: string;
  turns: number;
  steps: TurnStep[];
  compactions: { turn: number; identifier: string; originalChars: number; compactedChars: number }[];
  /** read_file calls that returned the "unchanged" marker instead of content. */
  markerReads: StaleReadFinding[];
  /** Paths whose content was replaced by a placeholder and never re-delivered in full afterwards. */
  pathsLost: string[];
  firstWriteTurn: number | null;
  /** Paths whose content was a placeholder in the request sent on the turn of the first write. */
  compactedAtFirstWrite: string[];
  testedAtTurn: number | null;
  builtAtTurn: number | null;
  filesWritten: string[];
  hiddenTestsPassed: boolean;
}

export interface GroupFinding {
  label: string;
  configuration: string;
  runs: RunFinding[];
  passCount: number;
  runCount: number;
  runsWithCompaction: number;
  runsWithMarkerReads: number;
  runsThatLostAFile: number;
  runsThatRanTests: number;
  runsThatWrote: number;
}

export interface TraceFindings {
  diagnosisId: string;
  baseline: GroupFinding;
  candidate: GroupFinding;
  /** Every other visited configuration (e.g. the isolating run that changes only contextPolicy). */
  isolating: GroupFinding[];
  /** All runs that FAILED, across groups — for statements like "every failing run shows X". */
  failingRuns: number;
  failingRunsWithLostFile: number;
}

function analyzeRun(result: ExperimentResult): RunFinding | null {
  const turns = result.evidence.trajectory?.turns;
  if (!turns || turns.length === 0) return null;

  const compactedAt = new Map<string, number>();
  const compactions: RunFinding["compactions"] = [];
  const markerReads: StaleReadFinding[] = [];
  const fullReadAfterCompaction = new Set<string>();
  const filesWritten: string[] = [];
  const steps: TurnStep[] = [];
  let firstWriteTurn: number | null = null;
  let compactedAtFirstWrite: string[] = [];
  let testedAtTurn: number | null = null;
  let builtAtTurn: number | null = null;

  for (const turn of turns) {
    for (const event of turn.request.newCompactionEvents) {
      compactions.push({ turn: turn.turn, identifier: event.identifier, originalChars: event.originalChars, compactedChars: event.compactedChars });
      if (!compactedAt.has(event.identifier)) compactedAt.set(event.identifier, turn.turn);
    }

    const compactedNow = turn.request.newCompactionEvents.map((e) => e.identifier);
    if (turn.toolCalls.length === 0) steps.push({ turn: turn.turn, kind: "final", target: null, compactedNow });

    for (const call of turn.toolCalls) {
      const path = typeof call.arguments.path === "string" ? call.arguments.path : null;
      const command = typeof call.arguments.command === "string" ? call.arguments.command : null;
      let kind: StepKind = "other";
      if (call.name === "list_files") kind = "list";
      if (call.name === "read_file") kind = DEDUP_MARKER.test(call.resultSummary) ? "read_marker" : "read";
      if (call.name === "write_file") kind = "write";
      if (call.name === "run_command") kind = command && /\bnpm test\b/.test(command) ? "test" : command && /\bnpm run build\b/.test(command) ? "build" : "other";
      steps.push({ turn: turn.turn, kind, target: path ?? command, compactedNow });

      if (call.name === "read_file" && path) {
        const compacted = compactedAt.get(path) ?? null;
        if (DEDUP_MARKER.test(call.resultSummary)) {
          markerReads.push({ turn: turn.turn, path, compactedAtTurn: compacted });
        } else if (compacted !== null && turn.turn > compacted) {
          fullReadAfterCompaction.add(path);
        }
      }
      if (call.name === "write_file" && path) {
        if (firstWriteTurn === null) {
          firstWriteTurn = turn.turn;
          compactedAtFirstWrite = [...turn.request.compactedToolResultIdentifiers];
        }
        if (!filesWritten.includes(path)) filesWritten.push(path);
      }
      if (call.name === "run_command" && command) {
        if (testedAtTurn === null && /\bnpm test\b/.test(command)) testedAtTurn = turn.turn;
        if (builtAtTurn === null && /\bnpm run build\b/.test(command)) builtAtTurn = turn.turn;
      }
    }
  }

  const pathsLost = [...compactedAt.keys()].filter((p) => !fullReadAfterCompaction.has(p) && markerReads.some((m) => m.path === p && m.compactedAtTurn !== null));

  return {
    runId: result.runId,
    success: result.success,
    terminationReason: result.terminationReason,
    contextPolicy: turns[0].request.contextPolicy,
    turns: turns.length,
    steps,
    compactions,
    markerReads,
    pathsLost: pathsLost,
    firstWriteTurn,
    compactedAtFirstWrite,
    testedAtTurn,
    builtAtTurn,
    filesWritten,
    hiddenTestsPassed: result.evaluation.hiddenTestsPassed,
  };
}

function analyzeGroup(aggregate: ConfigurationAggregate): GroupFinding {
  const runs = aggregate.runs.map(analyzeRun).filter((r): r is RunFinding => r !== null);
  return {
    label: aggregate.label,
    configuration: aggregate.configurationVector,
    runs,
    passCount: runs.filter((r) => r.success).length,
    runCount: runs.length,
    runsWithCompaction: runs.filter((r) => r.compactions.length > 0).length,
    runsWithMarkerReads: runs.filter((r) => r.markerReads.length > 0).length,
    runsThatLostAFile: runs.filter((r) => r.pathsLost.length > 0).length,
    runsThatRanTests: runs.filter((r) => r.testedAtTurn !== null).length,
    runsThatWrote: runs.filter((r) => r.firstWriteTurn !== null).length,
  };
}

/** Returns null when the evidence carries no trajectories (e.g. a legacy or hand-trimmed file) — the page then simply omits the panel. */
export function computeTraceFindings(diagnosis: StableDiagnosisResult): TraceFindings | null {
  if (!diagnosis.baselineAggregate?.runs || !diagnosis.candidateAggregate?.runs || !Array.isArray(diagnosis.aggregates)) return null;

  const baseline = analyzeGroup(diagnosis.baselineAggregate);
  const candidate = analyzeGroup(diagnosis.candidateAggregate);
  if (baseline.runCount === 0 || candidate.runCount === 0) return null;

  const isolating = diagnosis.aggregates
    .filter((a) => a.configurationVector !== diagnosis.baselineAggregate.configurationVector && a.configurationVector !== diagnosis.candidateAggregate.configurationVector)
    .map(analyzeGroup)
    .filter((g) => g.runCount > 0);

  const all = [baseline, candidate, ...isolating].flatMap((g) => g.runs);
  const failing = all.filter((r) => !r.success);

  return {
    diagnosisId: diagnosis.diagnosisId,
    baseline,
    candidate,
    isolating,
    failingRuns: failing.length,
    failingRunsWithLostFile: failing.filter((r) => r.pathsLost.length > 0).length,
  };
}
